    if not math.isfinite(lr):
        raise ValueError("lr must be finite")
    if lr <= 0.0 or lr > 1.0:
        raise ValueError("lr must be in (0, 1]")
    if isinstance(damping, bool) or not isinstance(damping, (int, float)):
